# JSON-escape a single string on stdin -> stdout (no surrounding quotes).
# Handles \, ", and control chars 0x00-0x1F per RFC 8259.
json_escape_stdin() {
    awk 'BEGIN{
        for(i=0;i<32;i++) ctl[sprintf("%c",i)]=sprintf("\\u%04x",i);
        ctl[sprintf("%c",8)]="\\b";  ctl[sprintf("%c",9)]="\\t";
        ctl[sprintf("%c",10)]="\\n"; ctl[sprintf("%c",12)]="\\f";
        ctl[sprintf("%c",13)]="\\r";
    }
    {
        if (NR>1) printf "\\n";
        s=$0
        gsub(/\\/,"\\\\",s)
        gsub(/"/,"\\\"",s)
        out=""
        n=length(s)
        for(i=1;i<=n;i++){
            c=substr(s,i,1)
            if(c in ctl) out=out ctl[c]; else out=out c
        }
        printf "%s", out
    }'
}

json_escape() {
    printf '%s' "$1" | json_escape_stdin
}

# Build the JSON payload entirely in bash/awk (no python dependency).
build_audit_payload() {
    local mode="$1"
    local release="$2"
    local git_sha
    git_sha="$(git -C "${SCRIPT_DIR}" rev-parse HEAD 2>/dev/null || echo "unknown")"

    local entries="" sep="" key value encoded
    for key in "${VALIDATED_KEYS[@]}"; do
        if [[ "${mode}" == "full" ]]; then
            value="${!key}"
        else
            value="sha256:$(sha256_of "${!key}")"
        fi
        encoded="\"$(json_escape "${key}")\":\"$(json_escape "${value}")\""
        entries+="${sep}${encoded}"
        sep=","
    done

    printf '{"release":"%s","git_sha":"%s","timestamp":"%s","mode":"%s","schema_file":".env.test","config":{%s}}' \
        "$(json_escape "${release}")" \
        "$(json_escape "${git_sha}")" \
        "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
        "${mode}" \
        "${entries}"
}

