# JSON-escape a string read from stdin -> stdout (no surrounding quotes).
# Handles \, ", and control chars per RFC 8259.
# Note on awk gsub replacement strings: each literal backslash needs FOUR
# backslashes in the source ("\\\\" in awk -> "\\" in the replacement ->
# one literal "\" in output). So \ -> \\ is "\\\\\\\\", and " -> \" is
# "\\\\\"".
json_escape_stdin() {
    awk 'BEGIN{
        for(i=0;i<32;i++) ctl[sprintf("%c",i)]=sprintf("\\u%04x",i);
        ctl[sprintf("%c",8)]="\\b";  ctl[sprintf("%c",9)]="\\t";
        ctl[sprintf("%c",10)]="\\n"; ctl[sprintf("%c",12)]="\\f";
        ctl[sprintf("%c",13)]="\\r";
    }
    {
        if (NR>1) printf "\\n";
        s=$0
        gsub(/\\/,"\\\\\\\\",s)
        gsub(/"/,"\\\\\"",s)
        out=""
        n=length(s)
        for(i=1;i<=n;i++){
            c=substr(s,i,1)
            if(c in ctl) out=out ctl[c]; else out=out c
        }
        printf "%s", out
    }'
}

