cat > /tmp/mock_orch.pl <<'PL'
use strict; use warnings;
use IO::Socket::INET;
my $srv = IO::Socket::INET->new(LocalAddr=>'127.0.0.1', LocalPort=>47301,
    Proto=>'tcp', Listen=>5, ReuseAddr=>1) or die "bind: $!";
open(my $log, '>', '/tmp/mock_orch.log') or die $!;
$log->autoflush(1);
while (my $c = $srv->accept) {
    my $req = ""; my $clen = 0;
    while (my $line = <$c>) {
        $req .= $line;
        $clen = $1 if $line =~ /^Content-Length:\s*(\d+)/i;
        last if $line =~ /^\r?\n$/;
    }
    my $body = ""; if ($clen) { read($c, $body, $clen); }
    print $log "---REQ---\n$req\nBODY: $body\n---END---\n";
    print $c "HTTP/1.1 200 OK\r\nContent-Length: 11\r\nConnection: close\r\n\r\n{\"ok\":true}";
    close $c;
}
PL

perl /tmp/mock_orch.pl &
MOCK_PID=$!
